  "settings.radios.card.meta": "{{rig}} · CAT {{cat}}{{flex}} · audio {{audio}} · porta helper CAT {{port}}",
  "settings.radios.card.meta.flex": " · radio Flex {{ip}}",
  "settings.radios.card.omnirig": "Configurata in OmniRig",
